#include <stdio.h>

int height[201];
int adj[201][201];
int memo[201];

int longest_path(int u) {
    if (memo[u] != -1) return memo[u];

    int best = 0;
    for (int v = 1; v <= 200; v++) {
        if (adj[u][v] && height[v] < height[u]) {
            int length = 1 + longest_path(v);
            if (length > best) best = length;
        }
    }

    return memo[u] = best;
}

int main(void) {
    int S, T, P;
    scanf("%d %d %d", &S, &T, &P);

    for (int i = 1; i <= S; i++) {
        scanf("%d", &height[i]);
        memo[i] = -1;
    }

    for (int i = 0; i < T; i++) {
        int I, J;
        scanf("%d %d", &I, &J);
        adj[I][J] = adj[J][I] = 1;
    }

    printf("%d\n", longest_path(P));
    return 0;
}
