    for (int i = 0; i < T; i++) {
        int I, J;
        scanf("%d %d", &I, &J);
        --I;
        --J;

        if (height[I] > height[J]) {
            graph[I][J] = 1;
        } else if (height[J] > height[I]) {
            graph[J][I] = 1;
        }
    }

    int visited[200] = {0};
    int queue[200];
    int head = 0, tail = 0;

    queue[tail++] = P - 1;
    visited[P - 1] = 1;

    while (head < tail) {
        int u = queue[head++];
        for (int v = 0; v < S; v++) {
            if (graph[u][v] && !visited[v]) {
                visited[v] = 1;
                queue[tail++] = v;
            }
        }
    }

    int count = 0;
    for (int i = 0; i < S; i++) {
        if (visited[i] && i != P - 1) {
